function arrival_statement(arrival: IArrivalRow): SqlStatement {
  const template = ARRIVAL_STATEMENTS[arrival.rel];
  if (template === undefined) {
    throw new Error(`seeded_pre_multicolumn_fee_stats_fold: tick received an arrival for undeclared rel '${arrival.rel}'`);
  }
  if (arrival.sign === "del") {
    if (template.kind === "log") {
      throw new Error(`seeded_pre_multicolumn_fee_stats_fold: retract from log rel '${arrival.rel}' (engine.pl retract_from_log)`);
    }
    if (template.del_sql === null) {
      throw new Error(`seeded_pre_multicolumn_fee_stats_fold: rel '${arrival.rel}' has no delete statement`);
    }
    return { sql: template.del_sql, args: bind_args(arrival.row) };
  }
  return { sql: template.add_sql, args: bind_args(arrival.row) };
}

function apply_arrivals(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<unknown> {
  const statements: SqlStatement[] = arrivals.map(arrival_statement);
  return seam.runner.batch(seam.db, statements);
}

